import { useState } from 'react';
import { JxButton, JxDrawer } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type MenuDrawerProps = {
  onNavigate: (key: NavKey) => void;
};

const ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function MenuDrawer({ onNavigate }: MenuDrawerProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  const itemStyle = { width: '100%', justifyContent: 'flex-start' } as const;

  return (
    <>
      <JxButton variant="primary" onClick={() => setOpen(true)}>
        Меню
      </JxButton>

      <JxDrawer open={open} onOpenChange={setOpen} side="left" title="Меню">
        <nav
          aria-label="Основная навигация"
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-1)',
          }}
        >
          {ITEMS.map((item) => (
            <JxButton
              key={item.key}
              variant="ghost"
              style={itemStyle}
              onClick={() => select(item.key)}
            >
              {item.label}
            </JxButton>
          ))}

          <hr
            className="jx-divider"
            style={{ margin: 'var(--jx-space-2) 0', border: 'none', borderTop: '1px solid var(--jx-color-border)' }}
          />

          <JxButton
            variant="danger"
            style={itemStyle}
            onClick={() => select('logout')}
          >
            Выйти
          </JxButton>
        </nav>
      </JxDrawer>
    </>
  );
}

